242: export default function AppsPage() {
243:     const { t, lang } = useI18n();
244:     const { planExpired, currentPlan: guardPlan } = useExpiredPlanGuard();
245:     const router = useRouter();
246:     const TRACKING_APPS = getTrackingApps(t);
247:     const [loading, setLoading] = useState(true);
248:     const [saving, setSaving] = useState(false);
249:     const [userId, setUserId] = useState('');
250:     const [pixelData, setPixelData] = useState<any>({});
251:     const [selectedApp, setSelectedApp] = useState<string | null>(null);
252:     const [toast, setToast] = useState<{ msg: string; type: string } | null>(null);
253:     const [userPlan, setUserPlan] = useState<'free' | 'pro' | 'vip'>('free');
254:     const [appLimits, setAppLimits] = useState<any>({});
255: 
256:     const showToast = (msg: string, type = 'success') => {
257:         setToast({ msg, type });
258:         setTimeout(() => setToast(null), 3000);
259:     };
260: 
261:     useEffect(() => {
262:         async function load() {
263:             try {
264:                 const ctx = await getStoreContext();
265:                 if (!ctx) { router.push('/login'); return; }
266: 
267:                 // RBAC: Only owners and managers can manage apps
268:                 if (!hasPermission(ctx.role, 'manage_apps')) {
269:                     router.push('/merchant');
270:                     return;
271:                 }
272: 
273:                 const uid = ctx.targetUserId;
274:                 setUserId(uid);
275: 
276:                 // Use plan from context
277:                 let currentPlan = ctx.plan || 'free';
278:                 setUserPlan(currentPlan as any);
279: 
280:                 // Fetch App Limits from Super Admin Configs
281:                 const { data: settings } = await insforge.database
282:                     .from('platform_settings')
283:                     .select('app_plans')
284:                     .eq('id', 1)
285:                     .single();
286:                 if (settings?.app_plans) {
287:                     setAppLimits(settings.app_plans);
288:                 }
289: 
290:                 const { data, error } = await insforge.database
291:                     .from('store_pixels')
292:                     .select('*')
293:                     .eq('user_id', uid)
294:                     .single();
295: 
296:                 if (data) {
297:                     setPixelData(data);
298:                 } else if (error?.code === 'PGRST116') {
299:                     const { data: newRow } = await insforge.database
300:                         .from('store_pixels')
301:                         .insert({ user_id: uid })
302:                         .select()
303:                         .single();
304:                     if (newRow) setPixelData(newRow);
305:                 }
306:             } catch (err) { console.error(err); }
307:             finally { setLoading(false); }
308:         }
309:         load();
310:     }, [router]);
311: 
312:     const handleSave = async () => {
313:         setSaving(true);
314:         try {
315:             const { id, user_id, created_at, ...updateData } = pixelData;
316:             const { error } = await insforge.database
317:                 .from('store_pixels')
318:                 .update({ ...updateData, updated_at: new Date().toISOString() })
319:                 .eq('user_id', userId);
320: 
321:             if (!error) showToast(t('t_1fe0d7556'));
322:             else { console.error('[Apps Save Error]', error); showToast(t('t_3b403f21'), 'error'); }
323:         } catch (err) { console.error('[Apps Save Exception]', err); showToast(t('t_9634eda3'), 'error'); }
324:         finally { setSaving(false); }
325:     };
326: 
327:     const handleToggle = async (appId: string, enableKey: string) => {
328:         const newValue = !pixelData[enableKey];
329:         
330:         // Enforce limits if trying to enable
331:         if (newValue) {
332:             const limit = appLimits[appId]?.[userPlan] ?? 1;
333:             if (limit === 0) {
334:                 showToast(`هذه الميزة غير متاحة في خطتك الحالية (${userPlan === 'free' ? t('t_217db6d41') : userPlan === 'pro' ? t('t_74dcec9f') : t('t_15187dfac')})`, 'error');
335:                 return;
336:             }
337:         }
338: 
339:         const updated = { ...pixelData, [enableKey]: newValue };
340:         setPixelData(updated);
341: 
342:         try {
343:             const { error } = await insforge.database
344:                 .from('store_pixels')
345:                 .update({ [enableKey]: newValue, updated_at: new Date().toISOString() })
346:                 .eq('user_id', userId);
347: 
348:             if (!error) showToast(newValue ? t('t_6247efc1') : t('t_26be36a0'));
349:             else { setPixelData({ ...pixelData }); showToast(t('t_93a04e88'), 'error'); }
350:         } catch { showToast(t('t_9634eda3'), 'error'); }
351:     };
352: 
353:     const updateField = (key: string, value: string) => {
354:         setPixelData((prev: any) => ({ ...prev, [key]: value }));
355:     };
356: 
